package com.projectdark.mobile.world;
import android.graphics.*;import com.projectdark.mobile.RuntimeState;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class MillesGroundMaterialTest {
 @Test public void worldPixelsStayContinuousAcrossChunkEdgesAndCameraSteps(){MillesGroundMaterial m=new MillesGroundMaterial(RuntimeEnvironment.getApplication().getAssets());WorldRuntimeAdapter w=new WorldRuntimeAdapter(new RuntimeState(),320,256);w.camera().snapTo(1024,800);Bitmap a=Bitmap.createBitmap(320,256,Bitmap.Config.ARGB_8888);m.draw(new Canvas(a),w);int builds=m.builds();m.draw(new Canvas(a),w);assertEquals(builds,m.builds());w.camera().snapTo(1025,800);Bitmap b=Bitmap.createBitmap(320,256,Bitmap.Config.ARGB_8888);m.draw(new Canvas(b),w);for(int y=0;y<256;y++)for(int x=0;x<319;x++){assertEquals(255,Color.alpha(b.getPixel(x,y)));assertEquals("world phase at "+x+","+y,a.getPixel(x+1,y),b.getPixel(x,y));}}
 @Test public void tourIsBoundedAndMapExitReleasesAllFloorChunks(){MillesGroundMaterial m=new MillesGroundMaterial(RuntimeEnvironment.getApplication().getAssets());WorldRuntimeAdapter w=new WorldRuntimeAdapter(new RuntimeState(),320,256);Bitmap b=Bitmap.createBitmap(320,256,Bitmap.Config.ARGB_8888);for(int y=200;y<=1500;y+=260)for(int x=-300;x<=2200;x+=260){w.camera().snapTo(x,y);m.draw(new Canvas(b),w);assertTrue(m.entries()<=32);assertTrue(m.bytes()<=8652800);}assertEquals(32,m.entries());m.release();assertEquals(0,m.entries());assertEquals(0,m.bytes());}
}
